CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz);
CREATE TABLE invitations (id uuid PRIMARY KEY, code_hash text NOT NULL UNIQUE, max_uses integer NOT NULL CHECK (max_uses > 0), used_count integer NOT NULL DEFAULT 0 CHECK (used_count >= 0), expires_at timestamptz, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE email_verifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, code_hash text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, replaced_by uuid REFERENCES sessions(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE devices (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_device_id text NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(user_id, client_device_id));
CREATE TABLE archive_objects (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, sha256 char(64) NOT NULL, size_bytes bigint NOT NULL CHECK (size_bytes >= 0), object_key text NOT NULL UNIQUE, status text NOT NULL CHECK (status IN ('PENDING','VERIFIED','VERIFY_FAILED')), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, device_id, sha256));
CREATE TABLE object_authorizations (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, archive_object_id uuid REFERENCES archive_objects(id) ON DELETE SET NULL, operation text NOT NULL CHECK (operation IN ('UPLOAD','DOWNLOAD')), object_key text NOT NULL, expected_sha256 char(64) NOT NULL, expected_size_bytes bigint NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE authorization_audits (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id) ON DELETE SET NULL, device_id uuid REFERENCES devices(id) ON DELETE SET NULL, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotas (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, byte_limit bigint, object_limit integer, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id) WHERE revoked_at IS NULL;
CREATE INDEX archive_objects_lookup_idx ON archive_objects(user_id, device_id, sha256) WHERE status = 'VERIFIED';
CREATE INDEX authorizations_expiry_idx ON object_authorizations(expires_at) WHERE consumed_at IS NULL;
